import{z as A,x as B,o as t,c as p,q as l,j as n,D as r,d as e,s as i,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"最优子结构与重叠","description":"","frontmatter":{"title":"最优子结构与重叠","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/opt-substructure.md","filePath":"cs/opt-substructure.md","lastUpdated":1791063341000}'),d={name:"cs/opt-substructure.md"};function m(D,a,u,h,C,P){const s=B("Mermaid");return t(),p("div",null,[a[2]||(a[2]=l('<h1 id="最优子结构与重叠" tabindex="-1">最优子结构与重叠 <a class="header-anchor" href="#最优子结构与重叠" aria-label="Permalink to &quot;最优子结构与重叠&quot;">​</a></h1><div class="epigraph"><p>最优解含有某子问题的最优解；同一子问题在递归树里反复出现，才值得制成一张表。</p><footer>—— 据 Bellman, Dynamic Programming, 1957；CLRS 第 15 章整理</footer></div><p>上一课<a href="/cs/dynamic-programming">动态规划</a>已经把状态、转移、填表说成一套。钢条与 LCS 当了骨架，背包细节留给后课。本课不重画 DAG 填表序。缺口是把两条性质拆开钉死：<strong>最优子结构</strong>何时成立、<strong>重叠</strong>与分治的不相交有何不同——没有它们，表是空的或指数仍在。后课用容量把状态写成具体的 \\(dp[i][w]\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>最优子结构：原问题最优解里，对选中的那一次切分，左右（或剩余）必须是对应子问题的最优。证明通常用切割：若某块不是最优，换上更优块，原解变好，矛盾。失败典型：图上最长<strong>简单</strong>路——子路加边可能重复顶点，子路最优加起来不必简单，也不必全局最长。有环正权时「最优」甚至无界。缺口不是再解释 \\(\\min/\\max\\)，而是先问能不能切。</p><p>重叠：切法有多种，不同切法问到同一 \\((i,j)\\)。分治归并的左右区间不相交，备忘无收益。DP 故意让区间、前缀、容量被多次引用。没有重叠，指数递归仍可能正确，只是不必填表。</p><h3 id="子结构不是「能递归」" tabindex="-1">子结构不是「能递归」 <a class="header-anchor" href="#子结构不是「能递归」" aria-label="Permalink to &quot;子结构不是「能递归」&quot;">​</a></h3><p>DFS、快排都递归，没有「子答案必须最优」。贪心也要子结构，但另加「只需试一种切」。本课两条都要，且默认枚举切。</p><p><span class="marginnote">Bellman 的最优化原理即子结构。CLRS 15.3 专节讲何时成立。本课把它从「DP 总则」里抽出来，避免背包课再从原理讲起。</span></p><p><span class="marginnote">术语翻译：最优子结构 = 「大问题的最优答案里，必拼着一小块小问题的最优答案」；重叠 = 「不同的切法会反复问到同一道小题」。DP 做的事就是把小题答案写进一张表，第二个人再问时直接查表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>定义子问题族（前缀、区间、点 \\(v\\) 的最短路）。证明：最优解选定一项转移后，剩余实例的最优可粘回。数清不同子问题个数；若多项式且每个多项式转移，则多项式。若个数指数（子集），算法可以正确但不在 P——<a href="/cs/p-vs-np">P 与 NP</a> 再命名。</p>',12)),(t(),n(o,null,{default:r(()=>[i(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20CUT%5B%22%E9%80%89%E5%AE%9A%E4%B8%80%E6%AC%A1%E5%88%87%22%5D%20--%3E%20OPTS%5B%22%E5%89%A9%E4%BD%99%E5%BF%85%E9%A1%BB%E6%9C%80%E4%BC%98%22%5D%0A%20%20OPTS%20--%3E%20OV%5B%22%E5%90%8C%E4%B8%80%E5%AD%90%E9%97%AE%E9%A2%98%E5%A4%9A%E6%AC%A1%E5%87%BA%E7%8E%B0%22%5D%0A%20%20OV%20--%3E%20TAB%5B%22%E5%A1%AB%E8%A1%A8%22%5D%0A%20%20OPTS%20--%3E%20FAIL%5B%22%E7%AE%80%E5%8D%95%E6%9C%80%E9%95%BF%E8%B7%AF%EF%BC%9A%E5%88%87%E5%AE%8C%E4%B8%8D%E5%86%8D%E5%90%88%E6%B3%95%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[e("无重叠 → 退回"),E("a",{href:"/cs/divide-conquer"},"分治"),e("。无子结构 → 不要 DP。")],-1)),a[4]||(a[4]=E("p",null,[E("span",{class:"marginnote"},"常见误区：初学者以为「能写成递归就能 DP」。快排、DFS 都递归，却没有「子答案必须最优」这一条；反过来只有重叠没有子结构（最长简单路），填出来的表也不存真答案。两条缺一不可，且要先检查再开表。")],-1)),a[5]||(a[5]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=E("p",null,"最短路（无负环）有子结构：最短路的子路是最短路。背包：用或不用第 \\(i\\) 件，剩余容量上的最优。区间：最优在某处切开，两段区间最优。后课背包把「容量」写成一维；本课只要求会检查这两条。",-1)),a[7]||(a[7]=E("p",null,"同为图上路径问题，为什么最短路能 DP、最长简单路不能：",-1)),(t(),n(o,null,{default:r(()=>[i(s,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20SP%5B%22%E6%9C%80%E7%9F%AD%E8%B7%AF%20(%E6%97%A0%E8%B4%9F%E7%8E%AF)%22%5D%20--%3E%20S1%5B%22%E5%AD%90%E8%B7%AF%20%3D%20%E5%AD%90%E9%97%AE%E9%A2%98%E7%9A%84%E6%9C%80%E7%9F%AD%E8%B7%AF%22%5D%0A%20%20S1%20--%3E%20S2%5B%22%E5%8F%AF%E7%B2%98%E5%9B%9E%3A%20%E6%80%A7%E8%B4%A8%E6%88%90%E7%AB%8B%2C%20%E5%A1%AB%E8%A1%A8%22%5D%0A%20%20LP%5B%22%E6%9C%80%E9%95%BF%E7%AE%80%E5%8D%95%E8%B7%AF%22%5D%20--%3E%20L1%5B%22%E5%AD%90%E8%B7%AF%E6%9C%80%E4%BC%98%20%2B%20%E5%86%8D%E5%8A%A0%E4%B8%80%E6%9D%A1%E8%BE%B9%22%5D%0A%20%20L1%20--%3E%20L2%5B%22%E5%8F%AF%E8%83%BD%E9%87%8D%E5%A4%8D%E9%A1%B6%E7%82%B9%2C%20%E4%B8%8D%E5%86%8D%E3%80%8E%E7%AE%80%E5%8D%95%E3%80%8F%22%5D%0A%20%20L2%20--%3E%20L3%5B%22%E6%80%A7%E8%B4%A8%E5%A4%B1%E8%B4%A5%2C%20%E9%80%80%E5%9B%9E%E6%8C%87%E6%95%B0%E6%90%9C%E7%B4%A2%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=l('<p>重叠用备忘或自底向上等价：拓扑序保证每个状态在依赖之后算。</p><p><span class="marginnote">数字实例：重叠有多夸张——裸递归算斐波那契 \\(\\mathrm{fib}(5)\\) 时 \\(\\mathrm{fib}(3)\\) 被问 2 次、\\(\\mathrm{fib}(2)\\) 被问 3 次；到 \\(n=50\\)，调用次数达百亿量级，而备忘录把子问题压到 50 个、每个只算一次。这就是「值得制表」的直觉。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 0-1 转移的滚动数组，不引入伪多项式这个词的完整讨论（背包课会用 \\(W\\)）。不证 NPC。后课默认：先问子结构与重叠，再开表。容量与三种背包是下一缺口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>最优子结构 = 切完剩余仍最优；最长简单路是反例。</li><li>重叠 = 子问题重复；无重叠则不必 DP。</li><li>表的大小下一课用背包实例化。</li><li>出处：Bellman, 1957；CLRS 第 15.3 节。</li></ul>',6))])}const b=A(d,[["render",m]]);export{c as __pageData,b as default};
